INSERT INTO `restaurants` (`id`, `name`, `category`, `area`, `price_range`, `description`, `address`, `image`, `emoji`, `created_at`) VALUES (1,'麺処 龍神 渋谷店','Japanese','渋谷','¥1,000〜¥3,000','じっくり炊き上げた濃厚豚骨スープと自家製細麺、秘伝の旨辛ダレが自慢の一杯','東京都渋谷区神南1-0-1（架空）','assets/images/real_rest_1.jpg',NULL,'2026-06-19 15:23:30'),(3,'鮨 潮彩 豊洲','Japanese','東京','¥3,000〜','毎朝届く新鮮な旬ネタを職人が丁寧に握るおまかせ寿司セット','東京都江東区豊洲6-0-2（架空）','assets/images/real_rest_3.jpg',NULL,'2026-06-19 15:23:30'),(4,'ピッツェリア ソラーレ中目黒','Italian','目黒','¥3,000〜','高温の薪窯で焼き上げるもちもち生地と完熟トマトの本格マルゲリータ','東京都目黒区青葉台1-0-3（架空）','assets/images/real_rest_4.jpg',NULL,'2026-06-19 15:23:30'),(5,'サイアムガーデン 丸の内','Thai','丸の内','¥1,000〜¥3,000','ココナッツ香るグリーンカレーとフレッシュハーブたっぷりの本格タイ料理','東京都千代田区丸の内2-0-4（架空）','assets/images/real_rest_5.jpg',NULL,'2026-06-19 15:23:30'),(6,'炭火焼肉 焔（ほむら）新宿','Korean','新宿','¥1,000〜¥3,000','厳選黒毛和牛カルビ・厚切り上タン塩・特製もみダレの贅沢焼肉弁当','東京都新宿区歌舞伎町1-0-5（架空）','assets/images/real_rest_6.jpg',NULL,'2026-06-19 15:23:30'),(15,'青山クラフトバーガー','Burger','港','¥1,000〜¥3,000','粗挽きビーフ100%のジューシーパティと特製バンズのスマッシュバーガー','東京都港区北青山2-0-6（架空）','assets/images/real_rest_15.jpg',NULL,'2026-11-08 02:54:29'),(16,'本郷ダイナー＆グリル','Burger','文京','〜¥1,000','とろけるチーズと香ばしいベーコンを重ねたボリューム満点グルメバーガー','東京都文京区本郷4-0-7（架空）','assets/images/real_rest_16.jpg',NULL,'2026-10-22 09:14:50'),(17,'江戸前天ぷら 銀杏','Japanese','銀座','¥1,000〜¥3,000','薄衣でサクッと揚げた海老と季節野菜の特製天丼・そばセット','東京都中央区銀座5-0-8（架空）','assets/images/real_rest_17.jpg',NULL,'2026-10-23 09:14:50'),(18,'トラットリア ヴェント麻布','Italian','麻布','¥3,000〜','香ばしい窯焼きピッツァと生ハム・季節前菜が人気のイタリアン食堂','東京都港区元麻布3-0-9（架空）','assets/images/real_rest_18.jpg',NULL,'2026-10-24 09:14:50'),(19,'赤坂 紅龍飯店','Chinese','千代田','¥1,000〜¥3,000','花椒の痺れと深いコクがクセになる本格四川麻婆豆腐と担々麺','東京都千代田区平河町2-0-10（架空）','assets/images/real_rest_19.jpg',NULL,'2026-10-25 09:14:50'),(20,'スパイスキッチン南風','Indian','中央','〜¥1,000','香り豊かな南インドミールスとスパイス香るチキンビリヤニの専門店','東京都中央区八重洲2-0-11（架空）','assets/images/real_rest_20.jpg',NULL,'2026-10-26 09:14:50'),(21,'韓流チキン ハヌル新大久保','Korean','新宿','¥1,000〜¥3,000','二度揚げでザクザク食感の甘辛ヤンニョムチキンとチーズキンパ','東京都新宿